-- 151: tudo que é página pública se edita na Plataforma (3.3).
-- A coluna seo_pages.conteudo (jsonb) guarda o miolo da página: herói, rotina,
-- módulos, FAQ, "veja também", guias ligados, chamada. Vazia, vale o conteúdo
-- do código (src/conteudo). E toda página que existe no código ganha a linha
-- dela aqui, para aparecer na aba Páginas; quem já tem a linha fica como está.
-- Só dados e uma coluna nova: nenhuma função, política ou fluxo muda.

alter table public.seo_pages add column if not exists conteudo jsonb;
comment on column public.seo_pages.conteudo is 'O miolo da página (herói, rotina, módulos, FAQ, veja também, guias, chamada), editado na Plataforma. Vazio: vale o conteúdo do código (src/conteudo).';

